-- Generated by Loom
-- Generator: satellite
-- Variant: record_tracking
-- Hash function: sha256
{{ config(materialized='incremental', incremental_strategy='append') }}
WITH present AS (
    SELECT DISTINCT
        LOWER(sha256(UPPER(TRIM(CAST(s.customer_id AS VARCHAR))))) AS customer_hk
    FROM {{ ref('stg_customers') }} AS s
    JOIN {{ ref('hub_customer') }} AS p
        ON LOWER(sha256(UPPER(TRIM(CAST(s.customer_id AS VARCHAR))))) = p.customer_hk
)
{% if is_incremental() %}
, latest_state AS (
    SELECT customer_hk, __is_deleted
    FROM (
        SELECT
            customer_hk,
            __is_deleted,
            ROW_NUMBER() OVER (
                PARTITION BY customer_hk
                ORDER BY __loaded_at DESC, __is_deleted DESC
            ) AS rn
        FROM {{ this }}
    ) AS ranked
    WHERE rn = 1
)
{% endif %}
SELECT
    p.customer_hk,
    localtimestamp AS __loaded_at,
    'crm' AS __record_source,
    FALSE AS __is_deleted
FROM present AS p
{% if is_incremental() %}
LEFT JOIN latest_state AS l
    ON p.customer_hk = l.customer_hk
WHERE l.customer_hk IS NULL
    OR l.__is_deleted = TRUE
UNION ALL
SELECT
    l.customer_hk,
    localtimestamp AS __loaded_at,
    'crm' AS __record_source,
    TRUE AS __is_deleted
FROM latest_state AS l
WHERE l.__is_deleted = FALSE
  AND l.customer_hk NOT IN (
        SELECT customer_hk FROM present
    )
{% endif %}
